@Composable
fun Counters() {
    var broken = 0                                         // never redraws: Compose can't observe it
    var lost by remember { mutableStateOf(0) }             // resets on rotation
    var kept by rememberSaveable { mutableStateOf(0) }     // survives rotation and process death

    Column {
        Button(onClick = { broken++ }) { Text("Broken: $broken") }
        Button(onClick = { lost++ }) { Text("remember: $lost") }
        Button(onClick = { kept++ }) { Text("rememberSaveable: $kept") }
    }
}

// Before: the field owns its text, so the screen can't read, reset or validate it.
@Composable
fun SearchBoxStateful() {
    var text by remember { mutableStateOf("") }
    TextField(value = text, onValueChange = { text = it })
}

// After: stateless, the screen decides.
@Composable
fun SearchBox(query: String, onQueryChange: (String) -> Unit, modifier: Modifier = Modifier) {
    TextField(value = query, onValueChange = onQueryChange, modifier = modifier, placeholder = { Text("Search") })
}

class SearchViewModel : ViewModel() {
    private val _query = MutableStateFlow("")
    val query = _query.asStateFlow()
    fun onQueryChange(text: String) { _query.value = text.take(50) }       // the rule lives here
}

@Composable
fun SearchScreen(vm: SearchViewModel = viewModel()) {
    val query by vm.query.collectAsStateWithLifecycle()
    SearchBox(query, vm::onQueryChange)
}

@Composable
fun ProductList(products: List<Product>, onClick: (Int) -> Unit, onRemove: (Int) -> Unit) {
    LazyColumn(
        contentPadding = PaddingValues(16.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        item { Text("${products.size} products", style = MaterialTheme.typography.labelLarge) }
        items(products, key = { it.id }) { product ->
            ProductCard(
                product = product,
                onAddToCart = { onClick(product.id) },
                modifier = Modifier.animateItem(),          // smooth moves when the list changes
            )
        }
    }
}

@Composable
fun Catalogue(products: List<Product>) {
    val gridState = rememberLazyGridState()
    val scope = rememberCoroutineScope()
    val showTopButton by remember { derivedStateOf { gridState.firstVisibleItemIndex > 6 } }

    Box {
        LazyVerticalGrid(columns = GridCells.Adaptive(160.dp), state = gridState, contentPadding = PaddingValues(12.dp)) {
            items(products, key = { it.id }) { ProductTile(it) }
        }
        AnimatedVisibility(showTopButton, Modifier.align(Alignment.BottomEnd).padding(16.dp)) {
            FloatingActionButton(onClick = { scope.launch { gridState.animateScrollToItem(0) } }) {
                Icon(Icons.Default.KeyboardArrowUp, contentDescription = "Back to top")
            }
        }
    }
}

