class SignUpViewModel(private val auth: AuthRepository) : ViewModel() {
    private val _state = MutableStateFlow(SignUpState())
    val state = _state.asStateFlow()

    fun onEmail(v: String) = _state.update { it.copy(email = v.trim(), emailError = null) }
    fun onPassword(v: String) = _state.update { it.copy(password = v, passwordError = null) }

    fun submit() {
        val s = _state.value
        val emailError = SignUpValidator.email(s.email)
        val passwordError = SignUpValidator.password(s.password)
        if (emailError != null || passwordError != null) {
            _state.update { it.copy(emailError = emailError, passwordError = passwordError) }
            return
        }
        _state.update { it.copy(isSubmitting = true) }
        viewModelScope.launch {
            val result = auth.signUp(s.email, s.password)
            _state.update { it.copy(isSubmitting = false, emailError = result.exceptionOrNull()?.message) }
        }
    }
}

@Composable
fun OrderTracking(orderId: Int, onDelivered: () -> Unit, vm: TrackingViewModel = viewModel()) {
    val currentOnDelivered by rememberUpdatedState(onDelivered)

    // Restarts only when the order changes, not on every recomposition.
    LaunchedEffect(orderId) {
        vm.track(orderId).collect { status -> if (status == Status.DELIVERED) currentOnDelivered() }
    }

    val scope = rememberCoroutineScope()
    val sheet = rememberModalBottomSheetState()
    Button(onClick = { scope.launch { sheet.show() } }) { Text("Contact courier") }   // from a click

