@Composable
fun ExpandableFaq(question: String, answer: String) {
    var open by rememberSaveable { mutableStateOf(false) }
    val rotation by animateFloatAsState(if (open) 180f else 0f, label = "arrow")
    Column(Modifier.clickable { open = !open }.animateContentSize().padding(16.dp)) {
        Row {
            Text(question, Modifier.weight(1f))
            Icon(Icons.Default.ExpandMore, contentDescription = null, modifier = Modifier.rotate(rotation))
        }
        if (open) Text(answer, Modifier.padding(top = 8.dp))
    }
}

