fun FavoriteToggle(isFavorite: Boolean, onToggle: (Boolean) -> Unit) {
    Box(
        Modifier
            .size(48.dp)                                                 // minimum touch target
            .toggleable(value = isFavorite, role = Role.Switch, onValueChange = onToggle)
            .semantics { stateDescription = if (isFavorite) "In favourites" else "Not in favourites" },
        contentAlignment = Alignment.Center,
    ) {
        Icon(
            if (isFavorite) Icons.Default.Favorite else Icons.Default.FavoriteBorder,
            contentDescription = "Favourite",
        )
    }
}

class OrdersContentTest {
    @get:Rule val compose = createComposeRule()

    @Test fun emptyStateOffersToBrowse() {
        var browsed = false
        compose.setContent { OrdersContent(state = OrdersState(orders = emptyList()), onBrowse = { browsed = true }) }
        compose.onNodeWithText("No orders yet").assertIsDisplayed()
        compose.onNodeWithText("Browse products").performClick()
        assertTrue(browsed)
    }

    @Test fun errorShowsRetry() {
        compose.setContent { OrdersContent(state = OrdersState(error = "No connection"), onBrowse = {}) }
        compose.onNodeWithText("No connection").assertIsDisplayed()
        compose.onNodeWithText("Try again").assertIsEnabled()
    }
}

