// A classic View inside Compose
@Composable
fun LegacyRatingBar(rating: Float, onRating: (Float) -> Unit) {
    AndroidView(
        factory = { context -> RatingBar(context).apply { numStars = 5; stepSize = 0.5f } },
        update = { bar ->
            bar.rating = rating
            bar.setOnRatingBarChangeListener { _, value, fromUser -> if (fromUser) onRating(value) }
        },
    )
}
